import{_ as t,o,c as s,a7 as a}from"./chunks/framework.xMNG87v2.js";const f=JSON.parse('{"title":"Minecraft can’t connect to a server on the same computer on Windows","description":"Minecraft for Windows is not able to connect to a server on the same computer. Not the case as of the GDK migration.","frontmatter":{"title":"Minecraft can’t connect to a server on the same computer on Windows","outline":"deep","description":"Minecraft for Windows is not able to connect to a server on the same computer. Not the case as of the GDK migration.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/faq/connecting/win10localhostcantconnect"}]]},"headers":[],"relativePath":"docs/faq/connecting/win10localhostcantconnect.md","filePath":"docs/faq/connecting/win10localhostcantconnect.md","lastUpdated":1790689997000}'),n={name:"docs/faq/connecting/win10localhostcantconnect.md"};function i(c,e,r,l,d,h){return o(),s("div",null,[...e[0]||(e[0]=[a('<div class="info custom-block"><p class="custom-block-title">Note</p><p>This is not a case anymore since Minecraft for Windows migrated from UWP to GDK</p></div><h1 id="minecraft-can-t-connect-to-a-server-on-the-same-computer-on-windows" tabindex="-1">Minecraft can’t connect to a server on the same computer on Windows <a class="header-anchor" href="#minecraft-can-t-connect-to-a-server-on-the-same-computer-on-windows" aria-label="Permalink to &quot;Minecraft can&#39;t connect to a server on the same computer on Windows&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Note</p><p>These steps are <strong>not</strong> required to connect to all servers. You only need to do this if you’re connecting to a server on the <strong>same computer</strong> that you’re running Minecraft on.</p></div><h2 id="disable-uwp-loopback-restrictions-for-minecraft" tabindex="-1">Disable UWP loopback restrictions for Minecraft <a class="header-anchor" href="#disable-uwp-loopback-restrictions-for-minecraft" aria-label="Permalink to &quot;Disable UWP loopback restrictions for Minecraft&quot;">​</a></h2><p>Windows UWP apps have some restrictions on what they are allowed to do by default. Unfortunately, this includes connecting to things on localhost.</p><p>To lift this restriction from Minecraft, launch Windows PowerShell as an administrator and run the following:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CheckNetIsolation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LoopbackExempt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Microsoft.MinecraftUWP_8wekyb3d8bbwe&quot;</span></span></code></pre></div><p>For Minecraft Preview, you’ll need a slightly different command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CheckNetIsolation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LoopbackExempt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Microsoft.MinecraftWindowsBeta_8wekyb3d8bbwe&quot;</span></span></code></pre></div><p>If everything goes well, you’ll see a message: <code>OK.</code> You should now be able to connect (you may need to close and reopen the game).</p><h2 id="don-t-use-localhost-for-server-address" tabindex="-1">Don’t use <code>localhost</code> for server address <a class="header-anchor" href="#don-t-use-localhost-for-server-address" aria-label="Permalink to &quot;Don&#39;t use `localhost` for server address&quot;">​</a></h2><p>Minecraft for Windows doesn’t correctly handle the <code>localhost</code> address.</p><p>Try using <code>127.0.0.1</code> (IPv4) or <code>::1</code> (IPv6) instead when adding the server to your server list.</p>',13)])])}const u=t(n,[["render",i]]);export{f as __pageData,u as default};
